code.cpp:
class Solution {
public:
    string destCity(vector<vector<string>>& paths) {
        unordered_set<string> sources;
        sources.reserve(paths.size());
        for (const auto& p : paths) {
            sources.insert(p[0]);
        }
        for (const auto& p : paths) {
            if (sources.find(p[1]) == sources.end()) {
                return p[1];
            }
        }
        return "";
    }
};
